import { staticFile } from "remotion";

// Generated by `npm run sounds` (scripts/gen-sounds.mjs) into public/sfx and public/music.

export const SFX_NAMES = [
  "stamp_slam",
  "whoosh",
  "ripple",
  "war_drum",
  "clash",
  "waves",
  "gong",
  "crowd_cheer",
  "rumble",
  "impact",
  "crackle",
  "coins",
  "page_flip",
  "pop",
  "sparkle",
  "fanfare",
  "wind",
  "swell",
] as const;
export type SfxName = (typeof SFX_NAMES)[number];

export const MUSIC_MOODS = ["epic_tense", "mysterious", "sad_strings", "triumphant"] as const;
export type MusicMood = (typeof MUSIC_MOODS)[number];

/** Seamless-loop lengths (seconds) — keep in sync with gen-sounds.mjs (8 bars each). */
export const MUSIC_LOOP_SEC: Record<MusicMood, number> = { epic_tense: 19.2, mysterious: 24, sad_strings: (60 / 66) * 32, triumphant: (60 / 112) * 32 };
/** SFX that are loops (ambiences). */
export const SFX_LOOPS: Partial<Record<SfxName, number>> = { waves: 8, crackle: 4, wind: 8 };

export const sfxSrc = (n: SfxName) => staticFile(`sfx/${n}.wav`);
export const musicSrc = (m: MusicMood) => staticFile(`music/${m}.wav`);
export const voiceSrc = (ep: string) => staticFile(`voice/${ep}/voice.wav`);
export const captionsSrc = (ep: string) => staticFile(`voice/${ep}/captions.json`);

/** Default volume per SFX (0..1) so a mix sounds balanced without tweaking. */
export const SFX_GAIN: Partial<Record<SfxName, number>> = {
  fanfare: 0.55,
  wind: 0.3,
  swell: 0.6,
  stamp_slam: 0.68,
  whoosh: 0.41,
  ripple: 0.45,
  war_drum: 0.6,
  clash: 0.41,
  waves: 0.22,
  gong: 0.45,
  crowd_cheer: 0.34,
  rumble: 0.52,
  impact: 0.68,
  crackle: 0.26,
  coins: 0.38,
  page_flip: 0.45,
  pop: 0.38,
  sparkle: 0.34,
};
